from common import *
dom('html')

# ---------------------------------------------------------------- BEGINNER (+20)
topic('Document Structure')
M('b','k',"Which element wraps all the content that is visible in the browser window?","<body>","<head>","<html-content>","<main-window>","body holds everything the user sees; head holds metadata such as the title and linked files.")
M('b','k',"What is the correct way to write a comment in HTML?","<!-- this is a comment -->","// this is a comment","/* this is a comment */","# this is a comment","HTML comments start with <!-- and end with -->. The other forms belong to other languages.")
M('b','k',"Which element sets the text shown on the browser tab?","<title>","<header>","<h1>","<caption>","The title element inside head provides the tab text, bookmark name and search result title.")
T('b',"HTML is a markup language, not a programming language.",True,"HTML describes the structure of content with tags. It has no loops, variables or logic of its own.")
M('b','k',"What is the usual file extension of a web page written in HTML?",".html",".htm5",".web",".xml","Both .html and .htm are accepted by servers, but .html is the standard modern choice.")
topic('Text & Headings')
M('b','k',"Which element is used for the least important heading?","<h6>","<h0>","<h9>","<small-head>","Headings run from h1 (most important) to h6 (least important).")
M('b','k',"Which element marks a paragraph of text?","<p>","<para>","<text>","<pg>","The p element creates a paragraph; browsers add space above and below it.")
M('b','k',"Which element inserts a single line break inside a paragraph?","<br>","<lb>","<break>","<newline>","br forces a line break and has no closing tag.")
M('b','k',"Which element tells the browser that text is strongly important?","<strong>","<bold-text>","<big>","<mark-up>","strong carries meaning (importance) and is shown bold by default. b only changes the look.")
M('b','k',"Which element is used to emphasise text, usually shown in italics?","<em>","<i-bold>","<emph>","<slant>","em adds stress emphasis, which screen readers can voice differently.")
M('b','o',"What does a browser show for <p>Hello <b>big</b> world</p>?","The sentence Hello big world with only the word big in bold","The sentence with every word in bold","The literal text including the b tags","Only the word big, the rest is hidden","b is an inline element, so it styles just its own text inside the paragraph.")
topic('Links, Images & Media')
M('b','k',"Which attribute of the a element holds the address the link goes to?","href","src","link","target-url","href (hypertext reference) contains the destination URL.")
M('b','k',"Which attribute of the img element holds the path to the picture file?","src","href","path","file","src (source) tells the browser which image file to load.")
M('b','k',"Which element embeds a video player on the page?","<video>","<movie>","<media-play>","<embed-video>","video, with a src or nested source elements, plays video natively without plugins.")
topic('Lists & Tables')
M('b','k',"Which element creates a numbered list?","<ol>","<ul>","<nl>","<num>","ol is an ordered list. Each item inside it is an li element.")
M('b','k',"Which element defines one row in a table?","<tr>","<td>","<row>","<th>","tr is a table row; td and th are the cells inside it.")
M('b','k',"Which element defines a heading cell in a table?","<th>","<td>","<head-cell>","<tt>","th is a header cell. It is bold and centred by default and helps screen readers.")
topic('Forms & Input')
M('b','k',"Which input type hides the characters while the user types?","password","secret","hidden","mask","type='password' shows dots instead of the characters. type='hidden' shows nothing at all and is not for typing.")
M('b','k',"Which attribute shows grey hint text inside an empty input?","placeholder","hint","value-hint","tooltip","placeholder text disappears when the user starts typing. It does not replace a label.")
M('b','k',"Which attribute gives an element a unique name that CSS and JavaScript can target?","id","class-name","key","unique","An id should appear only once per page, unlike class which can be reused.")

# ---------------------------------------------------------------- INTERMEDIATE (+15)
topic('Semantics & Elements')
M('i','k',"What is the main difference between div and span?","div is a block-level container and span is an inline container","div can hold text but span cannot","span is for links and div is for images","There is no difference in default display","div starts on a new line and stretches across; span stays inside the line of text. Neither has any meaning of its own.")
M('i','k',"Which element provides a visible caption for a figure element?","<figcaption>","<legend>","<caption>","<label>","figcaption is the caption of a figure. caption belongs to tables and legend to fieldset.")
M('i','k',"What is the purpose of the noscript element?","Content shown only when scripting is disabled or unsupported","It stops scripts from running on the page","It marks a script as optional","It hides a script from search engines","Browsers with JavaScript turned off render the noscript content; others ignore it.")
T('i',"The b element and the strong element have exactly the same meaning.",False,"strong means strong importance. b only draws attention (for example a keyword) without adding importance.")
M('i','k',"Which element groups the header rows of a table?","<thead>","<th-group>","<tableheader>","<head-row>","thead, tbody and tfoot split a table into logical sections, which helps styling and accessibility.")
topic('Forms & Input')
M('i','k',"Which attribute restricts what a text input accepts using a regular expression?","pattern","regex","match","validate","pattern='[A-Z]{3}[0-9]{2}' makes the browser reject values that do not match when the form is submitted.")
M('i','k',"Which input type shows a numeric field with spinner controls?","number","numeric","digit","integer","type='number' accepts numbers only, and min, max and step control the allowed values.")
M('i','k',"What does the autofocus attribute do?","Moves the keyboard focus to that element when the page loads","Makes the element larger when it is selected","Selects all the text inside the element","Scrolls the page to the top","Only one element per page should use it, otherwise the focus target is unpredictable.")
M('i','k',"Which markup connects a label to its input without using the for attribute?","<label>Email <input type='email'></label>","<label href='email'><input type='email'></label>","<label><input type='email'></label> placed after the field","<input type='email' label='Email'>","Wrapping the control inside the label creates an implicit association. Clicking the label focuses the input.")
M('i','k',"A button is placed inside a form and has no type attribute. What happens when it is clicked?","It submits the form","Nothing, because it needs onclick","It resets the form","It focuses the first field","The default type of a button is submit. Use type='button' for buttons that should not submit.")
S('i','k',"Which of these are boolean attributes that need no value?",["disabled","checked"],["href","value"],"A boolean attribute is true when present. href and value carry text that must be given.")
topic('Links, Images & Media')
M('i','k',"Which attribute of the video element shows the play, pause and volume controls?","controls","show-controls","player","buttons","Without controls the video has no visible interface unless you build one with JavaScript.")
M('i','k',"Which attribute on a link with target='_blank' stops the opened page from reaching window.opener?","rel='noopener'","rel='nofollow'","rel='external'","rel='bookmark'","noopener cuts the connection to the opener page, which protects against tab-nabbing. nofollow only tells search engines not to follow.")
topic('Document Structure')
M('i','k',"Which attribute makes a script download in parallel and run as soon as it is ready, in no guaranteed order?","async","defer","parallel","lazy","async scripts run as soon as they arrive. defer scripts wait for the document to finish parsing and keep their order.")

# ---------------------------------------------------------------- ADVANCED (+28)
topic('Performance')
M('a','k',"What does loading='lazy' on an img element do?","Delays loading the image until it is close to the viewport","Loads the image at lower quality","Loads the image after all scripts have run","Prevents the image from being cached","Lazy loading saves bandwidth for images far below the fold. It should not be used on the main image at the top of the page.")
M('a','k',"A web font is preloaded with <link rel='preload' as='font' href='/f.woff2'>. Why is the font downloaded twice in some browsers?","The crossorigin attribute is missing","The type attribute is missing","Fonts cannot be preloaded","The link must be placed in the body","Fonts are fetched in CORS mode, so a preload without crossorigin does not match the later request and is wasted.")
M('a','k',"What is the purpose of <img srcset='a.jpg 480w, b.jpg 960w' sizes='(max-width: 600px) 100vw, 600px'>?","Let the browser pick a file based on the layout width and screen density","Show a.jpg on phones and b.jpg on desktops only","Display both images side by side","Resize the image with JavaScript","The w descriptors tell the browser the real width of each file. sizes tells it how wide the image will be drawn, so it can choose the smallest sufficient file.")
M('a','s',"A page jumps while images load, which causes layout shift. Which HTML change helps most?","Add width and height attributes to the images","Add loading='lazy' to every image","Move the images into the head","Use the async attribute on the images","With width and height the browser reserves space using the aspect ratio before the file arrives.")
S('a','s',"Which changes can help the main hero image appear faster?",["fetchpriority='high' on the image","A preload link for the image"],["loading='lazy' on the image","defer on the image"],"High priority and preloading start the download early. Lazy loading delays it, and defer is not an attribute of img.")
M('a','k',"What is true about <link rel='stylesheet' href='print.css' media='print'> when the page is viewed on screen?","It does not block the first render of the screen","It blocks rendering until it has loaded","It is ignored and never downloaded","It is applied to the screen after one second","A stylesheet whose media query does not match is not render-blocking, though it may still be downloaded at low priority.")
M('a','k',"How does a script with type='module' behave by default?","It is deferred and runs in strict mode","It runs immediately and blocks parsing","It runs only after a user click","It can only be inline","Module scripts are deferred like defer, run in strict mode and have their own scope.")
topic('Accessibility')
M('a','k',"What does aria-live='polite' do on an element?","Screen readers announce its changes when the user is idle","It makes the element visible to screen readers only","It reads the changes immediately and interrupts speech","It stops the element from being read","polite waits for a pause. assertive interrupts the current speech and is reserved for urgent messages.")
M('a','k',"When is aria-labelledby preferred over aria-label?","When the visible text of another element already names the control","When the control has no text anywhere on the page","When the page has no id attributes","When the element is a paragraph","aria-labelledby points to existing visible text by id, so the spoken name always matches what users see.")
M('a','k',"What does tabindex='-1' do?","Makes an element focusable by script or click but removes it from the Tab order","Moves the element to the start of the Tab order","Disables the element","Makes the element visible only to screen readers","Negative tabindex is useful for moving focus to a heading or dialog programmatically. tabindex='0' adds an element to the natural order.")
M('a','s',"A button contains only an SVG icon of a trash can and a screen reader announces it as just 'button'. What is the best fix?","Add aria-label='Delete item' to the button","Add alt='Delete item' to the button","Add title to the svg and nothing else","Replace the button with a div","aria-label gives the button an accessible name. alt is valid only on images and similar elements.")
M('a','s',"An element looks like a link but only runs JavaScript to open a menu. What should it be?","A button element","An a element with href='#'","A div with role='link'","An a element with href='javascript:void(0)'","Links navigate. Controls that perform actions are buttons, which are focusable and keyboard-operable by default.")
M('a','k',"What does the lang attribute on the html element help with?","Screen reader pronunciation, translation tools and correct hyphenation","Loading the right JavaScript library","Choosing the server language","Selecting a keyboard layout","Assistive technology and browsers use the declared language, for example lang='en', to pick voices, fonts and spelling rules.")
M('a','k',"Which attribute on a th element tells assistive technology whether it heads a column or a row?","scope","headers-for","axis","role-type","scope='col' or scope='row' links header cells with their data cells in simple tables.")
M('a','k',"What does the inert attribute do?","Makes an element and its children non-interactive and hidden from assistive technology","Makes an element invisible but still focusable","Disables only the mouse on the element","Prevents the element from being printed","inert is handy to block the page behind a custom modal. The content remains visible but cannot be focused or clicked.")
topic('Semantics & Elements')
M('a','k',"What does showModal() do on a dialog element?","Opens it in the top layer and makes the rest of the page inert","Opens it as an ordinary non-blocking box","Opens it in a new browser window","Hides every other dialog permanently","A modal dialog sits above all other content, gets a ::backdrop and traps interaction until it is closed.")
M('a','k',"What is the main feature of the template element?","Its content is parsed but not rendered, and stays inert until cloned by script","It renders its content only on mobile screens","It loads an external HTML file","It reuses a stylesheet","Scripts inside a template do not run and images are not loaded until the content is cloned into the document.")
M('a','k',"What does the time element's datetime attribute provide?","A machine-readable date or time","The time zone of the server","An automatic countdown","The time the page was last cached","<time datetime='2026-11-14'>14 November</time> lets software understand the human-friendly text.")
M('a','k',"What is the address element meant for?","Contact information for the nearest article or the page owner","Any postal address anywhere in the page","The URL of the current page","The server IP address","address is for contact details of the author or owner, not for arbitrary addresses such as a shop in a listing.")
M('a','k',"Which element represents the result of a calculation or a user action inside a form?","<output>","<result>","<calc>","<answer>","output can use the for attribute to list the controls that contributed to the result.")
M('a','o',"What DOM does the parser build from <p>One<div>Two</div>?","A p containing One, followed by a separate div containing Two","A p that contains both One and a div","A div that contains a p","Nothing, the markup is rejected","A p cannot contain a div, so the parser closes the p when it meets the div start tag.")
topic('Security')
M('a','k',"What does <iframe sandbox src='...'> with an empty sandbox attribute do?","Applies every restriction, such as blocking scripts, forms and popups","Applies no restrictions","Only blocks cookies","Makes the frame read-only but allows scripts","An empty sandbox is the strictest setting. Tokens such as allow-scripts selectively relax it.")
M('a','k',"What does the integrity attribute on a script or link tag do?","The browser checks the downloaded file against a hash and refuses it if it differs","It encrypts the file during download","It signs the page with a certificate","It limits the file size","Subresource Integrity protects against a tampered CDN file. For cross-origin files it is used together with crossorigin.")
T('a',"A type='hidden' input prevents users from changing its value before the form is sent.",False,"Hidden fields are only hidden visually. Anyone can edit them with developer tools, so the server must never trust them.")
M('a','k',"Which header-like element in HTML can declare a Content Security Policy?","<meta http-equiv='Content-Security-Policy' content=\"default-src 'self'\">","<security policy='self'>","<link rel='csp' href='self'>","<script policy='self'>","The meta tag can carry a CSP, although an HTTP header is preferred because it also supports more directives.")
topic('Head & Metadata')
M('a','k',"Which element tells search engines which URL is the preferred version of duplicate pages?","<link rel='canonical' href='https://example.com/page'>","<meta name='duplicate' content='ignore'>","<base href='https://example.com/page'>","<link rel='original' href='https://example.com/page'>","rel='canonical' consolidates duplicate or near-duplicate URLs into one preferred address.")
M('a','k',"What does <meta name='robots' content='noindex'> request?","That search engines do not list the page in results","That the page cannot be opened by crawlers","That the page is deleted from the server","That the page loads without cookies","noindex asks search engines to keep the page out of results. It does not block access to the page.")
M('a','k',"What does the base element do?","Sets the base URL used to resolve relative URLs in the document","Defines the base font size","Sets the root folder of the server","Defines the first heading of the page","<base href='https://cdn.example.com/'> makes <img src='a.png'> load from that address. A page may have only one base element.")
topic('Forms & Input')
M('a','k',"Which form attribute is required to upload a file with a post request?","enctype='multipart/form-data'","enctype='text/plain'","accept-charset='file'","method='file'","Without multipart encoding the browser sends only the file name, not its contents.")
M('a','k',"Which attribute turns off the browser's built-in validation messages for a whole form?","novalidate","validate='off'","autocomplete='off'","formnovalidation","novalidate on the form stops required, pattern and type checks from blocking the submit.")
M('a','k',"Which autocomplete value helps password managers on a sign-up page?","new-password","password","current-password","off-password","new-password signals a field for creating a password, so managers can suggest a strong one. current-password is for sign-in.")

topic('Forms & Input')
M('i','k',"Which attribute limits a file upload field to certain file types?","accept","filter","types","allow","<input type='file' accept='image/png, .pdf'> hints which files the picker should offer. The server must still check the real file type.")
